def utc_date_key(timestamp):
    if type(timestamp) is not str or not _FORM.fullmatch(timestamp):
        raise ValueError("timestamp:invalid")
    if timestamp[-1] != "Z":
        hours, minutes = int(timestamp[-5:-3]), int(timestamp[-2:])
        if hours > 14 or minutes > 59 or hours == 14 and minutes != 0:
            raise ValueError("timestamp:invalid")
    try:
        value = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
        offset = value.utcoffset()
        if not 2000 <= value.year <= 2099 or abs(offset) is None or abs(offset) > 14 * 3600:
            raise ValueError
        # Convert to UTC by subtracting the offset
        utc_value = value - offset
        # Verify the UTC year is valid
        if not 2000 <= utc_value.year <= 2099:
            raise ValueError("timestamp:invalid")
        return utc_value.date().isoformat()
    except (ValueError, OverflowError):
        raise ValueError("timestamp:invalid") from None

