def evaluate_v2(rule, document):
    """Evaluate a v2 rule against a document.

    v2 rules have: kind="all"|"any"|"not"|"predicate", with children/child or path+test+value/bounds.
    Malformed v2 raises ValueError("<v2-path>:invalid_v2").
    """
    kind = rule["kind"]

    if kind == "all":
        # children must be a list
        if not isinstance(rule.get("children"), list):
            raise ValueError("$.invalid_v2:rule_list_required")
        return all(evaluate_v2(child, document) for child in rule["children"])

    if kind == "any":
        # children must be a list
        if not isinstance(rule.get("children"), list):
            raise ValueError("$.invalid_v2:rule_list_required")
        return any(evaluate_v2(child, document) for child in rule["children"])

    if kind == "not":
        # child must be a dict
        if not isinstance(rule.get("child"), dict):
            raise ValueError("$.invalid_v2:rule_required")
        return not evaluate_v2(rule["child"], document)

    if kind == "predicate":
        # Must have path (list), test, and optionally value or bounds
        path = rule.get("path")
        if not isinstance(path, list):
            raise ValueError("$.invalid_v2")

        test = rule.get("test")
        if test not in ("eq", "exists", "between"):
            raise ValueError("$.invalid_v2")

        if test == "eq":
            value = rule.get("value")
            if value is None:
                raise ValueError("$.invalid_v2")
            # Navigate path
            value_doc = document
            for key in path:
                if isinstance(value_doc, dict):
                    value_doc = value_doc.get(key)
                else:
                    value_doc = None
                if value_doc is None:
                    break
            # Strict equality: missing key (None) does NOT equal explicit null
            if value_doc is None:
                return False
            return value_doc == value

        elif test == "exists":
            # Navigate path
            value_doc = document
            for key in path:
                if isinstance(value_doc, dict):
                    value_doc = value_doc.get(key)
                else:
                    value_doc = None
                if value_doc is None:
                    break
            return value_doc is not None

        elif test == "between":
            bounds = rule.get("bounds")
            if not isinstance(bounds, list) or len(bounds) != 2:
                raise ValueError("$.invalid_v2")
            low, high = bounds
            if not isinstance(low, int) or not isinstance(high, int):
                raise ValueError("$.invalid_v2")
            if low > high:
                raise ValueError("$.invalid_v2")
            # Navigate path
            value_doc = document
            for key in path:
                if isinstance(value_doc, dict):
                    value_doc = value_doc.get(key)
                else:
                    value_doc = None
                if value_doc is None:
                    break
            # Only accept actual ints
            if not isinstance(value_doc, int):
                return False
            return low <= value_doc <= high

    raise ValueError("$.invalid_v2")

