        raise ValueError(path + ".revision:integer_range")
    if type(value["amount"]) is not int or not -1000 <= value["amount"] <= 1000:
        raise ValueError(path + ".amount:integer_range")

def apply_batch(state, batch):
    if type(batch) is not list or len(batch) > 8:
        raise ValueError("batch:invalid_size")

    # First, validate all events and check for conflicts/atomic issues
    # We need to validate the entire batch before any state changes
    validated = []
    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"
        try:
            _event(event, path)
        except ValueError:
            raise

        # Check for conflict: same ID, same revision, different content
        old = state["events"].get(event["id"])
        if old is not None and event["revision"] == old["revision"]:
            if event != old:
                raise ValueError(path + ":revision_conflict")

        validated.append((index, event))

    # Validate store capacity after all validations pass
    # (new events would be <= 8, duplicates don't increase count)

    # Now apply changes atomically
    # Track which accounts need their old contributions removed
    accounts_to_remove = {}
    accounts_to_add = {}

    for index, event in validated:
        old = state["events"].get(event["id"])
        if old is not None:
            # Higher revision: remove old contribution
            if event["revision"] > old["revision"]:
                accounts_to_remove[old["account"]] = old["amount"]
                # Add new contribution
                accounts_to_add[event["account"]] = event["amount"]
            # Same revision: already validated as identical, no change needed
            # Lower revision: ignore (no-op)
        else:
            # New event
            accounts_to_add[event["account"]] = event["amount"]

    # Apply changes: remove old contributions, add new ones
    for account, old_amount in accounts_to_remove.items():
        current_total = state["totals"].get(account, 0)
        # Remove the old contribution
        state["totals"][account] = current_total - old_amount

    for account, amount in accounts_to_add.items():
        state["totals"][account] = state["totals"].get(account, 0) + amount

    # Update events
    for index, event in validated:
        state["events"][event["id"]] = copy.deepcopy(event)

    return None

def snapshot(state):
    return {"events": [copy.deepcopy(state["events"][key]) for key in sorted(state["events"])],
