                elif value is None:
                    raise ValueError(f"{path}.value:scalar_required")
                else:
                    raise ValueError(f"{path}.value:scalar_required")
            if isinstance(value, str) and len(value) > 32:
                raise ValueError(f"{path}.value:scalar_required")
        elif op == "exists":
            if "path" not in node:
                raise ValueError(f"{path}.path:missing")
        elif op == "between":
            if "path" not in node:
                raise ValueError(f"{path}.path:missing")
            if "low" not in node:
                raise ValueError(f"{path}.low:missing")
            if "high" not in node:
                raise ValueError(f"{path}.high:missing")
            low, high = node["low"], node["high"]
            if isinstance(low, bool) or not isinstance(low, int):
                raise ValueError(f"{path}.low:integer_required")
            if isinstance(high, bool) or not isinstance(high, int):
                raise ValueError(f"{path}.high:integer_required")
            if low > high:
                raise ValueError(f"{path}.high:invalid_range")
        elif op in ("all", "any"):
            if "rules" not in node:
                raise ValueError(f"{path}.rules:rule_list_required")
            if len(node["rules"]) < 1 or len(node["rules"]) > 4:
                raise ValueError(f"{path}.rules:rule_list_required")
            for i, child in enumerate(node["rules"]):
                validate_node(child, f"{path}.rules[{i}]")
        elif op == "not":
            if "rule" not in node:
                raise ValueError(f"{path}.rule:missing")
            validate_node(node["rule"], f"{path}.rule")

    validate_node(rule, "$")

    def convert(node):
        op = node.get("op")
        if op in ("all", "any"):
            children = [convert(child) for child in node["rules"]]
            return {"kind": op, "children": children}
        if op == "not":
            child = convert(node["rule"])
            return {"kind": "not", "child": child}
        result = {"kind": "predicate", "path": [node["path"]], "test": op}
        if op == "eq":
            result["value"] = node["value"]
        elif op == "between":
            result["bounds"] = [node["low"], node["high"]]
        return result

    return convert(copy.deepcopy(rule))

